import re

def parse_strings(strings, format_str):
    placeholder_pattern = r'\{[^}]*\}'
    matches = list(re.finditer(placeholder_pattern, format_str))

    if not matches:
        raise ValueError("No placeholder found in format string")

    if len(matches) > 1:
        raise ValueError("Multiple placeholders not supported")

    placeholder = matches[0]
    prefix = format_str[:placeholder.start()]
    suffix = format_str[placeholder.end():]

    numbers = []
    for s in strings:
        if not s.startswith(prefix) or not s.endswith(suffix):
            raise ValueError(f"String '{s}' does not match format '{format_str}'")

        num_str = s[len(prefix):-len(suffix)] if suffix else s[len(prefix):]
        try:
            num = int(num_str)
        except ValueError:
            try:
                num = float(num_str)
            except ValueError:
                raise ValueError(f"Could not convert '{num_str}' to number")
        numbers.append(num)

    return numbers

